def build_report(stock, orders):
    result = allocate(stock, orders)
    remaining = result['remaining']

    decisions = {}
    rejected_ids = []
    for row in result['results']:
        order_id = row['id']
        if order_id in decisions:
            continue
        decisions[order_id] = row['accepted']
        if not row['accepted']:
            rejected_ids.append(order_id)

