        'accepted_unique': sum(1 for accepted in decisions.values() if accepted),
        'rejected_unique': len(rejected_ids),
        'units_reserved': sum(reserved_by_sku.values()),
        'reserved_by_sku': reserved_by_sku,
        'rejected_ids': rejected_ids,
    }
